    /**
     * Every attribute, in no particular order.
     */
    func attributes(txn: YTransaction?) throws  -> [String: YValue]
    
    /**
     * Deletes `length` (by default 1) child nodes from `index` on (`OutOfBounds` if there aren't
     * that many).
     */
