        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeYXmlObserver.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface YXmlObserver: handle missing in uniffiFree")
            }
        },
